// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CityVisit) predicate.CityVisit {
	return predicate.CityVisit(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CityVisit) predicate.CityVisit {
	return predicate.CityVisit(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CityVisit) predicate.CityVisit {
	return predicate.CityVisit(sql.NotPredicates(p))
}
